files.content:
* {
  box-sizing: border-box;
  margin: 0;
}

.page {
  display: grid;
  grid-template-columns: minmax(900px, auto) 330px;
  grid-template-rows: repeat(3, auto);
  gap: 25px;
  min-height: 100vh;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  line-height: 1.4;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.header {
  display: flex;
  justify-content: space-between;
  grid-column: 1 / -1;
  grid-row: 1 / 2;
  align-items: center;
  padding: 25px;
  background-color: #ffc802;
}

.header__title {
  font-weight: 800;
  font-size: 31px;
  text-transform: uppercase;
}

.menu {
  width: 17px;
  height: 17px;
  border: none;
  background-color: transparent;
  background-image: url(https://code.s3.yandex.net/web-code/images/burger-close.svg);
  background-repeat: no-repeat;
  background-position: center;
  cursor: pointer;
}

.menu:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.sidebar {
  display: flex;
  flex-direction: column;
  grid-column: 2 / -1;
  grid-row: 2 / -2;
  gap: 25px;
  padding: 25px;
  background-color: #ffc802;
}

.sidebar__title {
  font-weight: 800;
  font-size: 25px;
  text-transform: uppercase;
}

.other-goods {
  display: flex;
  flex-direction: column;
  gap: 25px;
  padding-left: 0;
  list-style-type: none;
}

.content {
  display: flex;
  flex-direction: column;
  grid-column: 1 / -2;
  grid-row: 2 / -2;
}

.cards {
  display: grid;
  flex-grow: 1;
  grid-template-columns: repeat(9, 1fr);
  grid-template-rows: repeat(9, 1fr);
  gap: 25px;
  padding-left: 25px;
  list-style-type: none;
}

.cards__item {
  display: flex;
}

.cards__item:nth-child(1) {
  grid-column: 1 / 5;
  grid-row: 1 / 6;
}

.cards__item:nth-child(2) {
  grid-column: -6 / -1;
  grid-row: 1 / 6;
}

.cards__item:nth-child(3) {
  grid-column: 1 / -1;
  grid-row: -1 / -5;
}

.card {
  display: flex;
  border: 1px solid #000;
  cursor: grab;
}

.card:active {
  cursor: grabbing;
}

.card_drag {
  opacity: 0.3;
}

.card.over {
  outline: 3px dotted #000;
}

.card__img {
  flex-grow: 1;
  width: 100%;
  max-width: 55%;
  min-height: 180px;
  border-inline-end: 1px solid #000;
  object-fit: cover;
  pointer-events: none;
}

.card__add-button {
  border: 1px solid #000;
  padding: 10px 40px;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: transparent;
}

.card__add-button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.card__add-button:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.card__text {
}

.card__content {
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 25px;
  background-color: #ffc802;
}

.footer {
  grid-column: 1 / -1;
  grid-row: -1 / -2;
}

.card_type_white .card__content {
  background-color: #fff;
}
